package edu.campusconnect.service;import org.springframework.stereotype.Service;import java.util.concurrent.ExecutorService;import java.util.concurrent.Executors;@Service public class NotificationService{private final ExecutorService executor=Executors.newFixedThreadPool(2);public void sendAsync(String message){executor.submit(()->System.out.println("[ASYNC NOTIFICATION] "+message+" | Thread: "+Thread.currentThread().getName()));}}